@* ── Profile Section ── *@
@{
    RenderFragment RenderProfileSection() => __builder2 =>
    {
        <section class="settings-section">
            <h2>Profile</h2>
            <p class="section-description">Manage your personal information and how others see you.</p>

            @if (_profile is not null)
