@* ── Notifications Section ── *@
@{
    RenderFragment RenderNotificationsSection() => __builder2 =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>
            <p class="section-description">Choose how and when you want to be notified.</p>

            @if (_editNotifications is not null)
            {
                <div class="toggle-group">
                    <div class="toggle-row">
                        <div>
                            <strong>Email Notifications</strong>
                            <p class="toggle-description">Receive notifications via email</p>
                        </div>
                        <label class="switch">
                            <input type="checkbox" @bind="_editNotifications.EmailNotifications" />
                            <span class="slider"></span>
                        </label>
                    </div>
                    <div class="toggle-row">
                        <div>
                            <strong>Push Notifications</strong>
                            <p class="toggle-description">Receive push notifications in your browser</p>
                        </div>
                        <label class="switch">
                            <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                            <span class="slider"></span>
                        </label>
                    </div>
                    <div class="toggle-row">
                        <div>
                            <strong>Weekly Digest</strong>
                            <p class="toggle-description">Get a weekly summary of activity</p>
                        </div>
                        <label class="switch">
                            <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                            <span class="slider"></span>
                        </label>
                    </div>
                </div>

                <h5 class="subsection-title">Muted Channels</h5>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var ch = channel;
                        <label class="channel-item">
                            <input type="checkbox"
                                   checked="@_editNotifications.MutedChannels.Contains(ch)"
                                   @onchange="e => ToggleMutedChannel(ch, (bool)e.Value!)" />
                            <span>@ch</span>
                        </label>
                    }
                </div>

                <div class="button-group">
                    <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                </div>
            }
        </section>
    };
}

@* ── Security Section ── *@
@{
    RenderFragment RenderSecuritySection() => __builder2 =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            @if (_security is not null)
            {
                <!-- Change Password Panel -->
                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                        <span>🔑 Change Password</span>
                        <span class="chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                    </button>
                    @if (_passwordPanelOpen)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label for="currentPw">Current Password</label>
                                <input id="currentPw" type="password" class="form-control"
                                       @bind="_currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPw">New Password</label>
                                <input id="newPw" type="password" class="form-control"
                                       @bind="_newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPw">Confirm Password</label>
                                <input id="confirmPw" type="password" class="form-control"
                                       @bind="_confirmPassword" />
                            </div>
                            @if (_security.LastPasswordChange.HasValue)
                            {
                                <p class="text-muted">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                            }
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    }
                </div>

                <!-- Two-Factor Authentication -->
                <div class="toggle-row" style="margin-top:1.5rem;">
                    <div>
                        <strong>Two-Factor Authentication</strong>
                        <p class="toggle-description">
                            Status:
                            <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="slider"></span>
                    </label>
                </div>

                <!-- Active Sessions -->
                <h5 class="subsection-title" style="margin-top:2rem;">Active Sessions</h5>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _security.Sessions[0].Id)
                                        {
                                            <button class="btn btn-danger-sm"
                                                    @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>

                <!-- Revoke Confirmation Dialog -->
                @if (_sessionToRevoke is not null)
                {
                    <div class="modal-backdrop" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation="true">
                            <h4>Revoke Session</h4>
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                            <div class="button-group">
                                <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                <button class="btn btn-outline" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            }
        </section>
    };
}

@* ── Appearance Section ── *@
@{
    RenderFragment RenderAppearanceSection() => __builder2 =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>
            <p class="section-description">Customize how the application looks and feels.</p>

            @if (_editAppearance is not null)
            {
                <div class="form-group">
                    <label><strong>Theme</strong></label>
                    <div class="radio-group">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            var t = theme;
                            <label class="radio-item">
                                <input type="radio" name="theme"
                                       value="@t"
                                       checked="@(_editAppearance.Theme == t)"
                                       @onchange="() => _editAppearance.Theme = t" />
                                <span>@t</span>
                            </label>
                        }
                    </div>
                </div>

                <div class="form-group">
                    <label><strong>Font Size</strong></label>
                    <div class="radio-group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            var s = size;
                            <label class="radio-item">
                                <input type="radio" name="fontSize"
                                       value="@s"
                                       checked="@(_editAppearance.FontSize == s)"
                                       @onchange="() => _editAppearance.FontSize = s" />
                                <span>@s</span>
                            </label>
                        }
                    </div>
                </div>

                <div class="form-group">
                    <label for="language"><strong>Language</strong></label>
                    <select id="language" class="form-control" @bind="_editAppearance.Language">
                        <option>English</option>
                        <option>Spanish</option>
                        <option>French</option>
                        <option>German</option>
                        <option>Japanese</option>
                        <option>Portuguese</option>
                    </select>
                </div>

                <div class="toggle-row">
                    <div>
                        <strong>Compact Mode</strong>
                        <p class="toggle-description">Reduce spacing for a denser layout</p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_editAppearance.CompactMode" />
                        <span class="slider"></span>
                    </label>
                </div>

                <!-- Live Preview -->
                <h5 class="subsection-title" style="margin-top:1.5rem;">Preview</h5>
                <div class="appearance-preview @GetPreviewClasses()">
                    <div class="preview-header">Dashboard</div>
                    <div class="preview-body">
                        <div class="preview-card">
                            <strong>Welcome back!</strong>
                            <p>This is a preview of your selected appearance settings.</p>
                        </div>
                        <div class="preview-card">
                            <strong>Recent Activity</strong>
                            <p>You have 3 new notifications and 2 pending tasks.</p>
                        </div>
                    </div>
                </div>

                <div class="button-group" style="margin-top:1rem;">
                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                </div>
            }
        </section>
    };
}

@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";

    // Toast
    private string? _toastMessage;
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _profile;
    private ProfileEdit? _editProfile;

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels = InMemorySettingsService.AllChannels;

    // Security
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
    }

    private async Task LoadAllSettings()
    {
        _profile = await SettingsService.GetProfileAsync();
        _editProfile = ProfileEdit.FromProfile(_profile);

        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = NotificationEdit.FromPrefs(_notificationPrefs);

        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _security.TwoFactorEnabled;

        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance = AppearanceEdit.FromSettings(_appearance);
    }

    private void SetActiveSection(string section) => _activeSection = section;

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🛡️",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // ── Toast ──
    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast() => _toastMessage = null;

    // ── Profile ──
    private async Task SaveProfile()
    {
        if (_editProfile is null) return;
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            _editProfile = ProfileEdit.FromProfile(_profile);
    }

    // ── Notifications ──
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (_editNotifications is null) return;
        if (muted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        if (_editNotifications is null) return;
        var updated = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ──
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || string.IsNullOrWhiteSpace(_currentPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _security = await SettingsService.GetSecuritySettingsAsync();
            _currentPassword = _newPassword = _confirmPassword = "";
            _passwordPanelOpen = false;
            await ShowToast("Password updated successfully!");
        }
        catch (InvalidOperationException ex)
        {
            await ShowToast(ex.Message, "error");
        }
    }

    private void ConfirmRevokeSession(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance ──
    private string GetPreviewClasses()
    {
        if (_editAppearance is null) return "";
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        if (_editAppearance is null) return;
        var updated = new AppearanceSettings(
            _editAppearance.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        await ShowToast("Appearance settings saved!");
    }

    // ── Mutable edit models ──
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static ProfileEdit FromProfile(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];

        public static NotificationEdit FromPrefs(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }

        public static AppearanceEdit FromSettings(AppearanceSettings s) => new()
        {
            Theme = s.Theme,
            FontSize = s.FontSize,
            Language = s.Language,
            CompactMode = s.CompactMode
        };
    }
}

