@code {
    private readonly string[] _sections = ["Profile", "Notifications", "Security", "Appearance"];
    private string _activeSection = "Profile";

    // Toast
    private string? _toastMessage;
    private string _toastType = "success";
    private CancellationTokenSource? _toastCts;

    // Profile
    private UserProfile? _profile;
    private ProfileEdit? _editProfile;

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private NotificationEdit? _editNotifications;
    private readonly List<string> _allChannels = InMemorySettingsService.AllChannels;

    // Security
    private SecuritySettings? _security;
    private bool _twoFactorEnabled;
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private AppearanceEdit? _editAppearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
    }

    private async Task LoadAllSettings()
    {
        _profile = await SettingsService.GetProfileAsync();
        _editProfile = ProfileEdit.FromProfile(_profile);

        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = NotificationEdit.FromPrefs(_notificationPrefs);

        _security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _security.TwoFactorEnabled;

        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance = AppearanceEdit.FromSettings(_appearance);
    }

    private void SetActiveSection(string section) => _activeSection = section;

    private static string GetSectionIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🛡️",
        "Appearance" => "🎨",
        _ => "⚙️"
    };

    // ── Toast ──
    private async Task ShowToast(string message, string type = "success")
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastType = type;
        StateHasChanged();

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        try
        {
            await Task.Delay(3000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast() => _toastMessage = null;

    // ── Profile ──
    private async Task SaveProfile()
    {
        if (_editProfile is null) return;
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
            _editProfile = ProfileEdit.FromProfile(_profile);
    }

    // ── Notifications ──
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (_editNotifications is null) return;
        if (muted && !_editNotifications.MutedChannels.Contains(channel))
            _editNotifications.MutedChannels.Add(channel);
        else if (!muted)
            _editNotifications.MutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        if (_editNotifications is null) return;
        var updated = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        await ShowToast("Notification preferences saved!");
    }

    // ── Security ──
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || string.IsNullOrWhiteSpace(_currentPassword))
        {
            await ShowToast("Please fill in all password fields.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", "error");
            return;
        }
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _security = await SettingsService.GetSecuritySettingsAsync();
            _currentPassword = _newPassword = _confirmPassword = "";
            _passwordPanelOpen = false;
            await ShowToast("Password updated successfully!");
        }
        catch (InvalidOperationException ex)
        {
            await ShowToast(ex.Message, "error");
        }
    }

    private void ConfirmRevokeSession(ActiveSession session) => _sessionToRevoke = session;
    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _security = await SettingsService.GetSecuritySettingsAsync();
        _sessionToRevoke = null;
        await ShowToast("Session revoked.");
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }

    // ── Appearance ──
    private string GetPreviewClasses()
    {
        if (_editAppearance is null) return "";
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    private async Task SaveAppearance()
    {
        if (_editAppearance is null) return;
        var updated = new AppearanceSettings(
            _editAppearance.Theme,
            _editAppearance.FontSize,
            _editAppearance.Language,
            _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _appearance = updated;
        await ShowToast("Appearance settings saved!");
    }

    // ── Mutable edit models ──
    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";

        public static ProfileEdit FromProfile(UserProfile p) => new()
        {
            DisplayName = p.DisplayName,
            Email = p.Email,
            AvatarUrl = p.AvatarUrl,
            Bio = p.Bio
        };
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = [];

        public static NotificationEdit FromPrefs(NotificationPrefs p) => new()
        {
            EmailNotifications = p.EmailNotifications,
            PushNotifications = p.PushNotifications,
            WeeklyDigest = p.WeeklyDigest,
            MutedChannels = new List<string>(p.MutedChannels)
        };
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "Light";
        public string FontSize { get; set; } = "Medium";
        public string Language { get; set; } = "English";
        public bool CompactMode { get; set; }

        public static AppearanceEdit FromSettings(AppearanceSettings s) => new()
        {
            Theme = s.Theme,
            FontSize = s.FontSize,
            Language = s.Language,
            CompactMode = s.CompactMode
        };
    }
}

