@{
    RenderFragment RenderSecuritySection() => __builder2 =>
    {
        <section class="settings-section">
            <h2>Security</h2>
            <p class="section-description">Manage your password, two-factor authentication, and active sessions.</p>

            @if (_security is not null)
            {
                <!-- Change Password Panel -->
                <div class="expandable-panel">
                    <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                        <span>🔑 Change Password</span>
                        <span class="chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
                    </button>
                    @if (_passwordPanelOpen)
                    {
                        <div class="panel-body">
                            <div class="form-group">
                                <label for="currentPw">Current Password</label>
                                <input id="currentPw" type="password" class="form-control"
                                       @bind="_currentPassword" />
                            </div>
                            <div class="form-group">
                                <label for="newPw">New Password</label>
                                <input id="newPw" type="password" class="form-control"
                                       @bind="_newPassword" />
                            </div>
                            <div class="form-group">
                                <label for="confirmPw">Confirm Password</label>
                                <input id="confirmPw" type="password" class="form-control"
                                       @bind="_confirmPassword" />
                            </div>
                            @if (_security.LastPasswordChange.HasValue)
                            {
                                <p class="text-muted">Last changed: @_security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                            }
                            <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                        </div>
                    }
                </div>

                <!-- Two-Factor Authentication -->
                <div class="toggle-row" style="margin-top:1.5rem;">
                    <div>
                        <strong>Two-Factor Authentication</strong>
                        <p class="toggle-description">
                            Status:
                            <span class="status-badge @(_twoFactorEnabled ? "enabled" : "disabled")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </p>
                    </div>
                    <label class="switch">
                        <input type="checkbox" @bind="_twoFactorEnabled" />
                        <span class="slider"></span>
                    </label>
                </div>

                <!-- Active Sessions -->
                <h5 class="subsection-title" style="margin-top:2rem;">Active Sessions</h5>
                <div class="sessions-table-wrapper">
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != _security.Sessions[0].Id)
                                        {
                                            <button class="btn btn-danger-sm"
                                                    @onclick="() => ConfirmRevokeSession(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>

                <!-- Revoke Confirmation Dialog -->
                @if (_sessionToRevoke is not null)
                {
                    <div class="modal-backdrop" @onclick="CancelRevoke">
                        <div class="modal-dialog" @onclick:stopPropagation="true">
                            <h4>Revoke Session</h4>
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                            <div class="button-group">
                                <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                                <button class="btn btn-outline" @onclick="CancelRevoke">Cancel</button>
                            </div>
                        </div>
                    </div>
                }
            }
        </section>
    };
}

